}

#include <stdio.h>
int add_progress(int *value, int amount) {
    if (value == NULL || amount < 0 || *value > 100-amount) return 0;
    *value += amount;
    return 1;
}
int main(void){ int p=40; add_progress(&p,20); printf("%d\n",p); }

